"use strict";
// Lehrplan-Ergänzung Politik (KLP Wirtschaft-Politik NRW, IF 2, 3, 6, 7, 8, 11, 12): Sozialstaat, Verbraucher, Beruf, Internationale Politik, Medien/Extremismus, Nachhaltigkeit
(function () {
  const FACH = window.FAECHER.find((f) => f.id === "politik");
  if (!FACH) return;
  FACH.themen.push(
    {
      id: "sozialstaat",
      titel: "Soziale Sicherung",
      kurz: "Fünf Säulen der Sozialversicherung, Generationenvertrag, demografischer Wandel, Bürgergeld, Brutto und Netto",
      erklaerung: `<p>Das Grundgesetz nennt Deutschland in Artikel 20 einen <b>sozialen Bundesstaat</b>. Der <b>Sozialstaat</b> soll Menschen gegen die großen Lebensrisiken absichern: Krankheit, Unfall, Arbeitslosigkeit, Pflegebedürftigkeit und Alter. Kern ist die <b>Sozialversicherung</b> mit <b>fünf Säulen</b>: <b>Krankenversicherung</b> (seit 1883), <b>Unfallversicherung</b> (1884), <b>Rentenversicherung</b> (1889), <b>Arbeitslosenversicherung</b> (1927) und <b>Pflegeversicherung</b> (1995).</p>
<p>Die Beiträge werden als Prozentsatz vom <b>Bruttolohn</b> berechnet und in der Regel <b>je zur Hälfte</b> von Arbeitnehmer und Arbeitgeber gezahlt (paritätisch); nur die Unfallversicherung zahlt der Arbeitgeber allein. Was nach Abzug von Sozialabgaben und Lohnsteuer übrig bleibt, ist das <b>Netto</b>, das auf dem Konto landet. Grob gehen bei einem Durchschnittsverdiener 20 bis 25 Prozent des Bruttos für Sozialabgaben und noch einmal Steuern ab.</p>
<p>Die Sozialversicherung arbeitet nach dem <b>Solidarprinzip</b>: Alle zahlen nach ihrem Einkommen ein, Leistungen bekommt, wer sie braucht – der Gesunde zahlt für den Kranken, der Arbeitende für den Arbeitslosen. Bei einer privaten Versicherung gilt dagegen das Äquivalenzprinzip: Wer ein höheres Risiko hat, zahlt mehr. Das <b>Subsidiaritätsprinzip</b> besagt: Erst hilft man sich selbst oder in der Familie, dann der Staat.</p>
<p>Die Rente funktioniert im <b>Umlageverfahren</b>: Die Beiträge der heute Arbeitenden werden sofort als Rente an die heutigen Rentner ausgezahlt – das nennt man <b>Generationenvertrag</b>. Er gerät durch den <b>demografischen Wandel</b> unter Druck: Die Menschen leben länger und es werden weniger Kinder geboren. 1962 kamen auf einen Rentner noch etwa sechs Beitragszahler, heute sind es etwa zwei. Lösungsvorschläge sind ein höheres Rentenalter (es steigt bis 2031 auf 67 Jahre), höhere Beiträge, ein niedrigeres Rentenniveau, Zuwanderung oder zusätzliche private und betriebliche Vorsorge.</p>
<p>Wer keinen Anspruch aus der Versicherung hat oder dessen Einkommen nicht reicht, erhält aus Steuermitteln die <b>Grundsicherung</b>: seit 2023 das <b>Bürgergeld</b> (Nachfolger von „Hartz IV“) für Erwerbsfähige sowie die Grundsicherung im Alter. Dazu kommen Familienleistungen wie Kindergeld, Elterngeld, BAföG oder Wohngeld. Der Streit um den Sozialstaat dreht sich meist um <b>Gerechtigkeit</b>: Wie viel Umverteilung ist fair, wie viel Eigenverantwortung ist zumutbar?</p>`,
      aufgaben: [
        { t: "wahl", f: "Welche fünf Zweige bilden die gesetzliche Sozialversicherung?", a: ["Kranken-, Unfall-, Renten-, Arbeitslosen- und Pflegeversicherung", "Haftpflicht-, Hausrat-, Kfz-, Lebens- und Reiseversicherung", "Kranken-, Zahn-, Brillen-, Unfall- und Tierversicherung", "Renten-, Steuer-, Miet-, Schul- und Pflegeversicherung"], r: 0, info: "Die fünf Säulen sichern die Lebensrisiken Krankheit, Unfall, Alter, Arbeitslosigkeit und Pflegebedürftigkeit ab." },
        { t: "wahl", f: "Welche Säule der Sozialversicherung ist die jüngste?", a: ["Krankenversicherung", "Pflegeversicherung", "Rentenversicherung", "Unfallversicherung"], r: 1, info: "Die Pflegeversicherung kam 1995 dazu, die Krankenversicherung gibt es seit 1883." },
        { t: "wahl", f: "Wer zahlt die Beiträge zur Kranken-, Renten-, Arbeitslosen- und Pflegeversicherung?", a: ["Nur der Arbeitnehmer", "Nur der Arbeitgeber", "Arbeitnehmer und Arbeitgeber etwa je zur Hälfte", "Der Staat aus Steuern"], r: 2, info: "Das nennt man paritätische Finanzierung; nur die Unfallversicherung trägt der Arbeitgeber allein." },
        { t: "wahl", f: "Was bedeutet Solidarprinzip?", a: ["Jeder zahlt nur für sich selbst", "Wer ein höheres Risiko hat, zahlt mehr", "Alle zahlen nach Einkommen ein, Leistungen bekommt, wer sie braucht", "Nur Reiche müssen Beiträge zahlen"], r: 2, info: "Gesunde zahlen für Kranke, Junge für Alte – die Gemeinschaft trägt das Risiko gemeinsam." },
        { t: "wahl", f: "Was meint der Generationenvertrag?", a: ["Die heute Arbeitenden finanzieren mit ihren Beiträgen die heutigen Rentner", "Jeder spart für seine eigene Rente an", "Eltern und Kinder schließen einen Vertrag über das Erbe", "Der Staat verspricht jeder Generation gleich hohe Renten"], r: 0, info: "Das Umlageverfahren beruht auf dem Vertrauen, dass die nächste Generation später genauso zahlt." },
        { t: "wahl", f: "Was versteht man unter demografischem Wandel?", a: ["Die Zuwanderung aus dem Ausland", "Die Alterung der Gesellschaft durch längere Lebenserwartung und weniger Geburten", "Den Umzug vom Land in die Stadt", "Den Wandel der Berufe durch Digitalisierung"], r: 1, info: "Immer weniger Beitragszahler müssen immer mehr Rentner finanzieren." },
        { t: "wahl", f: "Welche Maßnahme gegen das Rentenproblem wurde bereits beschlossen?", a: ["Abschaffung der Rentenversicherung", "Rente ab 60 für alle", "Anhebung des Rentenalters schrittweise auf 67 Jahre", "Verbot privater Vorsorge"], r: 2, info: "Für Jahrgänge ab 1964 gilt die Regelaltersgrenze von 67 Jahren." },
        { t: "wahl", f: "Was ist das Bürgergeld?", a: ["Ein Geschenk des Staates an alle Bürger", "Die Grundsicherung für erwerbsfähige Menschen ohne ausreichendes Einkommen, seit 2023", "Die Rente für Beamte", "Das Taschengeld für Jugendliche"], r: 1, info: "Das Bürgergeld löste 2023 das Arbeitslosengeld II („Hartz IV“) ab und wird aus Steuern bezahlt." },
        { t: "wahl", f: "Was ist der Unterschied zwischen Brutto und Netto?", a: ["Brutto ist das Gehalt vor Abzügen, Netto das, was ausgezahlt wird", "Netto ist das Gehalt vor Abzügen, Brutto das, was ausgezahlt wird", "Brutto gilt für Angestellte, Netto für Selbstständige", "Es gibt keinen Unterschied"], r: 0, info: "Vom Brutto gehen Lohnsteuer und Sozialabgaben ab; das Netto landet auf dem Konto." },
        { t: "wahl", f: "Was bedeutet Subsidiaritätsprinzip im Sozialstaat?", a: ["Der Staat hilft zuerst, dann die Familie", "Erst hilft man sich selbst oder in der Familie, der Staat hilft nur, wenn das nicht reicht", "Nur Kirchen dürfen helfen", "Hilfe gibt es nur gegen Rückzahlung"], r: 1, info: "Die kleinere Einheit geht vor; der Staat springt nachrangig ein." },
        { t: "wahl", f: "Welche Leistung gehört NICHT zur Sozialversicherung, sondern wird aus Steuern bezahlt?", a: ["Krankengeld", "Arbeitslosengeld I", "Kindergeld", "Altersrente"], r: 2, info: "Kindergeld, Bürgergeld und Wohngeld sind steuerfinanzierte Leistungen ohne vorherige Beiträge." },
        { t: "zahl", f: "Jemand verdient 2.400 € brutto. Für Steuern und Sozialabgaben gehen zusammen 25 % ab. Wie hoch ist das Netto? (in €)", l: 1800, tol: 0.5, einheit: "€", info: "25 % von 2.400 € sind 600 €; 2.400 − 600 = 1.800 €." },
        { t: "zahl", f: "Der Beitrag zur Rentenversicherung beträgt 18,6 % vom Brutto und wird je zur Hälfte geteilt. Wie viel zahlt der Arbeitnehmer bei 2.000 € brutto? (in €)", l: 186, tol: 0.5, einheit: "€", info: "Die Hälfte von 18,6 % sind 9,3 %; 9,3 % von 2.000 € = 186 €." },
        { t: "zahl", f: "Der Arbeitnehmeranteil für Kranken-, Renten-, Arbeitslosen- und Pflegeversicherung beträgt zusammen etwa 21 %. Wie viel Sozialabgaben zahlt jemand mit 3.000 € brutto? (in €)", l: 630, tol: 0.5, einheit: "€", info: "21 % von 3.000 € = 0,21 · 3.000 = 630 €." },
        { t: "eingabe", f: "Wie heißt das Prinzip, nach dem die Beiträge der heute Arbeitenden sofort als Rente an die heutigen Rentner ausgezahlt werden? ___verfahren", l: ["Umlageverfahren", "Umlage"], info: "Im Gegensatz dazu steht das Kapitaldeckungsverfahren, bei dem jeder für sich anspart." },
        { t: "paare", f: "Ordne die Versicherung dem Risiko zu, das sie absichert", p: [["Krankenversicherung", "Arztbesuch und Krankenhaus"], ["Rentenversicherung", "Einkommen im Alter"], ["Arbeitslosenversicherung", "Verlust des Arbeitsplatzes"], ["Pflegeversicherung", "Hilfe bei Pflegebedürftigkeit"], ["Unfallversicherung", "Arbeitsunfall und Berufskrankheit"]] },
        { t: "reihenfolge", f: "Bringe die Sozialversicherungen in die Reihenfolge ihrer Einführung", items: ["Krankenversicherung (1883)", "Unfallversicherung (1884)", "Rentenversicherung (1889)", "Arbeitslosenversicherung (1927)", "Pflegeversicherung (1995)"] }
      ]
    },
    {
      id: "verbraucher",
      titel: "Verbraucher, Verträge, Geld",
      kurz: "Kaufvertrag, Widerruf, Gewährleistung, Abo-Fallen, Schufa, Konto, Dispo, Schulden, Haushaltsplan, Werbung",
      erklaerung: `<p>Ein <b>Kaufvertrag</b> kommt durch zwei übereinstimmende Willenserklärungen zustande: <b>Angebot</b> und <b>Annahme</b>. Das geht mündlich, per Klick oder Handschlag – ein Schriftstück ist nur selten nötig. Die Ware im Regal ist noch kein Angebot, sondern eine Einladung; das Angebot machst du an der Kasse. Beide Seiten haben Pflichten: Der Verkäufer liefert die mangelfreie Ware, der Käufer zahlt und nimmt sie ab.</p>
<p>Bei Käufen im Internet, per Telefon oder an der Haustür hast du ein <b>Widerrufsrecht von 14 Tagen</b>: Du kannst den Vertrag ohne Begründung rückgängig machen. Im Laden gibt es dieses Recht nicht – ein Umtausch ist dort freiwillig (Kulanz). Davon zu unterscheiden ist die <b>Gewährleistung</b>: Hat die Ware einen Mangel, haftet der <b>Verkäufer</b> gesetzlich <b>2 Jahre</b> lang (Reparatur oder Ersatz, sonst Preisminderung oder Rücktritt). Im ersten Jahr wird vermutet, dass der Mangel von Anfang an da war. Eine <b>Garantie</b> ist dagegen eine <b>freiwillige</b> Zusage des Herstellers mit eigenen Bedingungen.</p>
<p><b>Abo-Fallen</b> locken mit „kostenlos testen“ und verlängern sich automatisch. Schutz bieten die <b>Button-Lösung</b> (der Bestellknopf muss „zahlungspflichtig bestellen“ oder ähnlich heißen) und der <b>Kündigungsbutton</b>, den Online-Anbieter seit 2022 bereitstellen müssen. Verträge mit Minderjährigen sind ohne Zustimmung der Eltern schwebend unwirksam (Ausnahme Taschengeldparagraf). Hilfe bekommst du bei der <b>Verbraucherzentrale</b>.</p>
<p>Dein Geld liegt auf einem <b>Girokonto</b>; mit <b>Überweisung</b> (IBAN), Lastschrift, Girocard oder Handy bezahlst du bargeldlos. Eine <b>Kreditkarte</b> bucht erst später ab – das verführt zum Überziehen. Mit einem <b>Dispokredit</b> darfst du das Konto ins Minus ziehen, zahlst dafür aber hohe Zinsen (oft 10 bis 14 Prozent im Jahr). Die <b>Schufa</b> speichert, ob du Kredite und Rechnungen pünktlich bezahlst; ein schlechter Eintrag kann Handyvertrag oder Wohnung kosten.</p>
<p>Eine <b>Schuldenspirale</b> entsteht, wenn du Raten mit neuen Krediten bezahlst: Zinsen und Mahngebühren wachsen, bis das Einkommen nicht mehr reicht. Typische Auslöser sind Handy- und Online-Käufe auf Raten, Arbeitslosigkeit oder Trennung. Ausweg sind die <b>Schuldnerberatung</b> und notfalls die Privatinsolvenz (Restschuldbefreiung nach 3 Jahren). Vorbeugen hilft ein <b>Haushaltsplan</b>: Einnahmen und alle Ausgaben gegenüberstellen und eine Rücklage bilden.</p>
<p><b>Werbung</b> will Bedürfnisse wecken; sie arbeitet mit Gefühlen, Idolen und Zeitdruck („nur heute“). <b>Influencer</b> müssen bezahlte Beiträge als <b>Werbung kennzeichnen</b>. Algorithmen zeigen dir Angebote, die zu deinem Verhalten passen (personalisierte Werbung). Kritisch zu prüfen: Brauche ich das wirklich, was kostet es insgesamt, wer verdient daran?</p>`,
      aufgaben: [
        { t: "wahl", f: "Wodurch kommt ein Kaufvertrag zustande?", a: ["Nur durch Unterschrift auf Papier", "Durch Angebot und Annahme, also zwei übereinstimmende Willenserklärungen", "Erst durch die Bezahlung", "Erst durch die Lieferung"], r: 1, info: "Auch ein Klick auf „zahlungspflichtig bestellen“ oder ein „Ja“ an der Kasse ist eine Willenserklärung." },
        { t: "wahl", f: "Wie lange gilt das Widerrufsrecht bei Online-Käufen?", a: ["7 Tage", "14 Tage", "30 Tage", "2 Jahre"], r: 1, info: "Innerhalb von 14 Tagen kannst du ohne Begründung widerrufen; im Laden gibt es dieses Recht nicht." },
        { t: "wahl", f: "Wie lange dauert die gesetzliche Gewährleistung beim Kauf neuer Ware?", a: ["6 Monate", "1 Jahr", "2 Jahre", "5 Jahre"], r: 2, info: "Zwei Jahre lang haftet der Verkäufer für Mängel, die beim Kauf schon vorhanden waren." },
        { t: "wahl", f: "Was unterscheidet die Garantie von der Gewährleistung?", a: ["Die Garantie ist eine freiwillige Zusage des Herstellers, die Gewährleistung ist gesetzlich und trifft den Verkäufer", "Die Garantie ist gesetzlich, die Gewährleistung freiwillig", "Beides bedeutet dasselbe", "Die Garantie gilt nur für Lebensmittel"], r: 0, info: "Ohne Garantie hast du trotzdem deine Gewährleistungsrechte gegenüber dem Händler." },
        { t: "wahl", f: "Du kaufst eine Jacke im Laden und sie gefällt dir zu Hause nicht mehr. Was gilt?", a: ["Du hast 14 Tage Widerrufsrecht", "Der Händler muss die Jacke zurücknehmen", "Umtausch ist freiwillig (Kulanz), ein Recht darauf gibt es nicht", "Du kannst 2 Jahre lang zurückgeben"], r: 2, info: "Das Widerrufsrecht gilt nur für Fernabsatz- und Haustürgeschäfte; im Laden kannst du vorher prüfen." },
        { t: "wahl", f: "Was schreibt die Button-Lösung vor?", a: ["Der Bestellknopf muss eindeutig auf die Zahlungspflicht hinweisen", "Jeder Shop braucht einen roten Knopf", "Online-Bestellungen müssen per Telefon bestätigt werden", "Minderjährige dürfen nicht bestellen"], r: 0, info: "Formulierungen wie „zahlungspflichtig bestellen“ sollen Abo-Fallen verhindern." },
        { t: "wahl", f: "Was ist die Schufa?", a: ["Eine Behörde, die Steuern eintreibt", "Eine Auskunftei, die speichert, wie zuverlässig jemand Rechnungen und Kredite bezahlt", "Eine Bank für Jugendliche", "Eine Versicherung gegen Schulden"], r: 1, info: "Banken, Händler und Vermieter fragen die Schufa ab, bevor sie Verträge abschließen." },
        { t: "wahl", f: "Was ist ein Dispokredit?", a: ["Ein zinsloses Darlehen der Bank", "Die Erlaubnis, das Girokonto gegen hohe Zinsen zu überziehen", "Ein Sparplan mit festen Raten", "Ein Kredit nur für Hauskäufe"], r: 1, info: "Dispozinsen liegen oft bei 10 bis 14 Prozent im Jahr – deutlich teurer als ein Ratenkredit." },
        { t: "wahl", f: "Was unterscheidet eine Kreditkarte von einer Girocard?", a: ["Mit der Kreditkarte wird der Betrag erst später gesammelt abgebucht", "Die Girocard funktioniert nur im Ausland", "Mit der Kreditkarte kann man kein Bargeld abheben", "Die Girocard ist immer teurer"], r: 0, info: "Weil das Geld nicht sofort vom Konto geht, verliert man leichter den Überblick." },
        { t: "wahl", f: "Wie gerät man typischerweise in eine Schuldenspirale?", a: ["Indem man einen Haushaltsplan führt", "Indem man alte Raten mit neuen Krediten bezahlt und Zinsen und Mahngebühren wachsen", "Indem man Geld auf ein Sparkonto legt", "Indem man bar bezahlt"], r: 1, info: "Jeder neue Kredit kostet Zinsen – am Ende reicht das Einkommen nicht einmal mehr für die Raten." },
        { t: "wahl", f: "Wohin kann sich jemand mit Schulden kostenlos wenden?", a: ["An die Schuldnerberatung", "An die Werbeagentur", "An die Schufa", "An den Dispo"], r: 0, info: "Schuldnerberatungen von Städten, Kirchen und Verbraucherzentralen helfen kostenlos." },
        { t: "wahl", f: "Was müssen Influencer tun, wenn sie für ein Produkt bezahlt werden?", a: ["Nichts, das ist ihre Privatsache", "Den Beitrag deutlich als Werbung kennzeichnen", "Das Produkt kostenlos verschenken", "Den Beitrag nach 24 Stunden löschen"], r: 1, info: "Schleichwerbung ist verboten; Zuschauer müssen erkennen, dass es sich um Werbung handelt." },
        { t: "wahl", f: "Welche Aussage über Werbung ist richtig?", a: ["Werbung informiert immer neutral über Produkte", "Werbung will Bedürfnisse wecken und arbeitet oft mit Gefühlen und Zeitdruck", "Werbung ist für Jugendliche verboten", "Werbung zeigt alle Nachteile eines Produkts"], r: 1, info: "Sprüche wie „nur heute“ oder Idole sollen dich zum schnellen Kauf bewegen." },
        { t: "zahl", f: "Haushaltsplan: Einnahmen 1.800 € Lohn und 250 € Kindergeld. Ausgaben: 750 € Miete, 400 € Lebensmittel, 60 € Handy und Internet, 90 € Versicherungen, 150 € Freizeit. Wie viel bleibt am Monatsende übrig? (in €)", l: 600, tol: 0.5, einheit: "€", info: "Einnahmen 2.050 € minus Ausgaben 1.450 € = 600 €." },
        { t: "zahl", f: "Du überziehst dein Konto ein ganzes Jahr lang um 1.000 €. Der Dispozins beträgt 12 % pro Jahr. Wie viel Zinsen zahlst du? (in €)", l: 120, tol: 0.5, einheit: "€", info: "12 % von 1.000 € = 120 € – nur für das Überziehen." },
        { t: "eingabe", f: "Wie nennt man das Recht, einen Online-Kauf innerhalb von 14 Tagen ohne Begründung rückgängig zu machen? ___recht", l: ["Widerrufsrecht", "Widerruf"], info: "Der Widerruf muss dem Händler klar mitgeteilt werden, zum Beispiel per E-Mail oder Formular." },
        { t: "paare", f: "Ordne die Begriffe ihrer Bedeutung zu", p: [["Gewährleistung", "Gesetzliche Haftung des Verkäufers für Mängel, 2 Jahre"], ["Garantie", "Freiwillige Zusage des Herstellers"], ["Widerruf", "Rücktritt vom Online-Kauf binnen 14 Tagen"], ["Dispo", "Erlaubtes Überziehen des Kontos gegen Zinsen"], ["Schufa", "Auskunft über Zahlungszuverlässigkeit"]] },
        { t: "reihenfolge", f: "Bringe die Schritte einer Schuldenspirale in die richtige Reihenfolge", items: ["Teurer Kauf auf Raten", "Rate kann nicht gezahlt werden, Mahngebühren kommen dazu", "Neuer Kredit, um die alten Raten zu zahlen", "Zinsen und Schulden wachsen weiter", "Schuldnerberatung und notfalls Privatinsolvenz"] }
      ]
    },
    {
      id: "beruf",
      titel: "Beruf und Arbeitswelt",
      kurz: "Duale Ausbildung, Bewerbung, Praktikum, Ausbildungsvertrag, Arbeitnehmerrechte, Mindestlohn, Tarifvertrag, Zukunftsberufe",
      erklaerung: `<p>Nach der Schule stehen dir mehrere Wege offen: eine <b>duale Ausbildung</b>, eine schulische Ausbildung (zum Beispiel in Pflege- oder Erzieherberufen), ein weiterführender Schulabschluss oder später ein Studium. Die <b>duale Ausbildung</b> findet an zwei Lernorten statt: im <b>Betrieb</b> (Praxis, 3 bis 4 Tage pro Woche) und in der <b>Berufsschule</b> (Theorie und allgemeine Fächer). Sie dauert je nach Beruf 2 bis 3,5 Jahre und endet mit der Prüfung vor der Industrie- und Handelskammer (IHK) oder Handwerkskammer (HWK). Es gibt über 300 anerkannte Ausbildungsberufe.</p>
<p>Ein <b>Praktikum</b> hilft, Berufe auszuprobieren und Kontakte zu knüpfen – oft ist es der Einstieg in die Ausbildung. Bei der <b>Berufsberatung der Agentur für Arbeit</b> kannst du kostenlos deine Stärken testen und Ausbildungsplätze suchen (auch online im Berufsinformationszentrum BiZ).</p>
<p>Die <b>Bewerbungsmappe</b> besteht aus <b>Anschreiben</b> (warum du, warum dieser Betrieb, höchstens eine Seite), optional einem <b>Deckblatt</b>, dem <b>Lebenslauf</b> (tabellarisch, mit Foto freiwillig) und den <b>Anlagen</b> (Zeugnisse, Praktikumsbescheinigungen, Zertifikate). Heute wird meist online oder per E-Mail als eine PDF-Datei beworben. Danach folgen Einstellungstest und <b>Vorstellungsgespräch</b>.</p>
<p>Der <b>Ausbildungsvertrag</b> muss schriftlich sein; bei Minderjährigen unterschreiben die Eltern mit. Er regelt Beruf, Dauer, Arbeitszeit, Urlaub, Vergütung und die <b>Probezeit</b> (1 bis 4 Monate). Azubis bekommen eine Ausbildungsvergütung, für die eine gesetzliche Mindestvergütung gilt. Das <b>Jugendarbeitsschutzgesetz</b> schützt unter 18-Jährige: höchstens 8 Stunden am Tag und 40 Stunden pro Woche, keine Nachtarbeit, mehr Urlaub.</p>
<p><b>Arbeitnehmerrechte</b> gelten für alle Beschäftigten: ein schriftlicher Arbeitsvertrag, der gesetzliche <b>Mindestlohn</b> (seit 1. Januar 2026: 13,90 € pro Stunde, ab 2027: 14,60 €), mindestens <b>24 Werktage Urlaub</b> bei einer Sechs-Tage-Woche (also vier Wochen), Lohnfortzahlung bei Krankheit für sechs Wochen, Kündigungsschutz und Kündigungsfristen, Mutterschutz. In Betrieben ab fünf Beschäftigten kann ein <b>Betriebsrat</b> gewählt werden, der die Interessen der Belegschaft vertritt (<b>Mitbestimmung</b>).</p>
<p>Ein <b>Tarifvertrag</b> wird zwischen <b>Gewerkschaft</b> und Arbeitgeberverband (oder einem einzelnen Unternehmen) ausgehandelt und legt Löhne, Arbeitszeit und Urlaub für eine ganze Branche fest – meist besser als das Gesetz. Scheitern die Verhandlungen, dürfen Gewerkschaften zum <b>Streik</b> aufrufen. Die <b>Digitalisierung</b> verändert die Arbeitswelt: Routinearbeiten übernehmen Maschinen und KI, gefragt sind IT-Berufe, Pflege, Handwerk für Energiewende (Elektro, Heizung, Solar) und Berufe, in denen Menschen mit Menschen arbeiten. Lebenslanges Lernen wird zur Normalität.</p>`,
      aufgaben: [
        { t: "wahl", f: "Was bedeutet „dual“ bei der dualen Ausbildung?", a: ["Man lernt zwei Berufe gleichzeitig", "Man lernt an zwei Orten: im Betrieb und in der Berufsschule", "Die Ausbildung dauert genau zwei Jahre", "Zwei Azubis teilen sich eine Stelle"], r: 1, info: "Praxis im Betrieb, Theorie in der Berufsschule – das ist das deutsche Erfolgsmodell." },
        { t: "wahl", f: "Wie lange dauert eine duale Ausbildung in der Regel?", a: ["6 Monate", "1 Jahr", "2 bis 3,5 Jahre", "5 bis 6 Jahre"], r: 2, info: "Die meisten Ausbildungen dauern drei Jahre; mit gutem Abschluss kann man verkürzen." },
        { t: "wahl", f: "Wer nimmt die Abschlussprüfung in der dualen Ausbildung ab?", a: ["Die Schule", "Die Agentur für Arbeit", "Die Industrie- und Handelskammer oder die Handwerkskammer", "Der Betriebsrat"], r: 2, info: "IHK und HWK sind die zuständigen Kammern für die meisten Ausbildungsberufe." },
        { t: "wahl", f: "Welche Bestandteile gehören in eine Bewerbungsmappe?", a: ["Anschreiben, Lebenslauf und Zeugnisse", "Nur ein Foto", "Kontoauszüge und Ausweiskopie", "Eine Liste der Hobbys der Eltern"], r: 0, info: "Optional kommen Deckblatt und Praktikumsbescheinigungen dazu." },
        { t: "wahl", f: "Was gehört in das Anschreiben einer Bewerbung?", a: ["Alle Schulnoten der letzten vier Jahre", "Warum du dich für diesen Beruf und diesen Betrieb interessierst und was du mitbringst", "Eine Liste aller Freunde", "Die Gehaltsvorstellung deiner Eltern"], r: 1, info: "Höchstens eine Seite, auf den Betrieb zugeschnitten, ohne Rechtschreibfehler." },
        { t: "wahl", f: "Wozu dient ein Praktikum?", a: ["Es ersetzt die Ausbildung", "Es bringt automatisch einen Arbeitsvertrag", "Man lernt einen Beruf in der Praxis kennen und knüpft Kontakte", "Es ist nur für Studenten gedacht"], r: 2, info: "Viele Betriebe stellen Azubis ein, die sie schon aus dem Praktikum kennen." },
        { t: "wahl", f: "Wo bekommst du kostenlose Berufsberatung?", a: ["Bei der Schufa", "Bei der Berufsberatung der Agentur für Arbeit", "Beim Finanzamt", "Bei der Verbraucherzentrale"], r: 1, info: "Die Agentur für Arbeit bietet Beratung, Tests und die Ausbildungsplatzsuche an." },
        { t: "wahl", f: "Was muss für einen Ausbildungsvertrag gelten?", a: ["Er muss schriftlich sein; bei Minderjährigen unterschreiben die Eltern mit", "Ein Handschlag reicht", "Er darf keine Probezeit enthalten", "Er wird von der Berufsschule ausgestellt"], r: 0, info: "Er regelt Dauer, Arbeitszeit, Urlaub, Vergütung und Probezeit (1 bis 4 Monate)." },
        { t: "wahl", f: "Wie hoch ist der gesetzliche Mindestlohn seit dem 1. Januar 2026?", a: ["9,50 €", "12,00 €", "13,90 €", "16,00 €"], r: 2, info: "Die Mindestlohnkommission hat 13,90 € für 2026 und 14,60 € für 2027 festgelegt." },
        { t: "wahl", f: "Wie viel Urlaub steht Arbeitnehmern gesetzlich mindestens zu?", a: ["10 Werktage", "24 Werktage bei einer Sechs-Tage-Woche (vier Wochen)", "40 Werktage", "Es gibt keinen Anspruch"], r: 1, info: "Bei einer Fünf-Tage-Woche entspricht das 20 Arbeitstagen; Tarifverträge geben meist mehr." },
        { t: "wahl", f: "Wer handelt einen Tarifvertrag aus?", a: ["Bundestag und Bundesrat", "Gewerkschaft und Arbeitgeberverband", "Agentur für Arbeit und Betrieb", "Schule und Betrieb"], r: 1, info: "Der Tarifvertrag gilt für eine ganze Branche und ist meist besser als das Gesetz." },
        { t: "wahl", f: "Was regelt das Jugendarbeitsschutzgesetz für unter 18-Jährige?", a: ["Sie dürfen gar nicht arbeiten", "Höchstens 8 Stunden am Tag und 40 Stunden pro Woche, keine Nachtarbeit", "Sie müssen mindestens 10 Stunden am Tag arbeiten", "Sie bekommen keinen Urlaub"], r: 1, info: "Jugendliche sollen vor Überlastung und gefährlichen Arbeiten geschützt werden." },
        { t: "wahl", f: "Ab wie vielen Beschäftigten kann in einem Betrieb ein Betriebsrat gewählt werden?", a: ["Ab 5", "Ab 50", "Ab 500", "Nur in Konzernen"], r: 0, info: "Der Betriebsrat vertritt die Belegschaft und hat Mitbestimmungsrechte, etwa bei Arbeitszeiten." },
        { t: "wahl", f: "Wie verändert die Digitalisierung die Arbeitswelt?", a: ["Es gibt keine Veränderung", "Routinearbeiten übernehmen Maschinen und KI, neue Berufe in IT und Technik entstehen", "Alle Menschen verlieren ihre Arbeit", "Nur Büroberufe sind betroffen"], r: 1, info: "Wer sich weiterbildet, hat die besten Chancen – lebenslanges Lernen wird normal." },
        { t: "zahl", f: "Ein Nebenjob wird mit dem Mindestlohn von 13,90 € pro Stunde bezahlt. Wie viel verdienst du bei 20 Stunden im Monat? (in €)", l: 278, tol: 0.5, einheit: "€", info: "20 · 13,90 € = 278 €." },
        { t: "eingabe", f: "Wie heißt der Zeitraum am Anfang einer Ausbildung, in dem beide Seiten ohne Angabe von Gründen kündigen können? ___zeit", l: ["Probezeit", "Probe"], info: "Die Probezeit dauert in der Ausbildung mindestens einen und höchstens vier Monate." },
        { t: "paare", f: "Ordne die Begriffe ihrer Bedeutung zu", p: [["Berufsschule", "Theorie-Lernort der dualen Ausbildung"], ["Tarifvertrag", "Lohn- und Arbeitszeitregeln für eine Branche"], ["Betriebsrat", "Vertretung der Beschäftigten im Betrieb"], ["Mindestlohn", "Gesetzliche Untergrenze pro Stunde"], ["Streik", "Arbeitsniederlegung als Druckmittel der Gewerkschaft"]] },
        { t: "reihenfolge", f: "Bringe die Teile einer Bewerbungsmappe in die übliche Reihenfolge", items: ["Anschreiben", "Deckblatt", "Lebenslauf", "Zeugnisse und Praktikumsbescheinigungen"] }
      ]
    },
    {
      id: "international",
      titel: "Internationale Politik",
      kurz: "UN und Sicherheitsrat, NATO, Menschenrechte, Flucht und Migration, Asylrecht, Entwicklungszusammenarbeit, Klimakonferenzen",
      erklaerung: `<p>Die <b>Vereinten Nationen (UN)</b> wurden am 24. Oktober <b>1945</b> nach dem Zweiten Weltkrieg gegründet, um Frieden zu sichern, Menschenrechte zu schützen und Zusammenarbeit zu fördern. Heute gehören ihnen <b>193 Staaten</b> an; Sitz ist New York. In der <b>Generalversammlung</b> hat jeder Staat eine Stimme. Der <b>Sicherheitsrat</b> entscheidet über Frieden und Krieg: Er hat <b>15 Mitglieder</b>, davon <b>fünf ständige</b> mit <b>Vetorecht</b> – USA, Russland, China, Frankreich und Großbritannien – und zehn nichtständige, die für zwei Jahre gewählt werden. Legt eine Vetomacht ihr Veto ein, ist der Beschluss blockiert; das lähmt die UN oft. Weitere Organe sind der Generalsekretär, der Internationale Gerichtshof in Den Haag und Unterorganisationen wie UNICEF, WHO und UNHCR. <b>Blauhelme</b> sind UN-Friedenssoldaten, die Waffenstillstände überwachen.</p>
<p>Am 10. Dezember <b>1948</b> verabschiedete die UN-Generalversammlung die <b>Allgemeine Erklärung der Menschenrechte (AEMR)</b> mit 30 Artikeln: Recht auf Leben und Freiheit, Verbot von Folter und Sklaverei, Meinungs- und Religionsfreiheit, Recht auf Bildung und Asyl. Menschenrechte gelten für alle Menschen, überall, von Geburt an – sie sind unveräußerlich. Die Erklärung ist kein bindendes Gesetz, aber Maßstab für Verträge und Verfassungen weltweit.</p>
<p>Die <b>NATO</b> ist ein Verteidigungsbündnis, gegründet <b>1949</b>; Deutschland trat 1955 bei, heute hat sie 32 Mitglieder. Kern ist <b>Artikel 5</b>: Ein Angriff auf ein Mitglied gilt als Angriff auf alle (Bündnisfall, bisher nur nach dem 11. September 2001 ausgerufen). Die Bundeswehr ist eine <b>Parlamentsarmee</b>: Auslandseinsätze muss der Bundestag genehmigen.</p>
<p><b>Flucht und Migration</b> haben viele Ursachen (<b>Push-Faktoren</b>): Krieg, Verfolgung, Armut, Hunger, Klimawandel; <b>Pull-Faktoren</b> wie Sicherheit, Arbeit und Familie ziehen in bestimmte Länder. Weltweit sind über 100 Millionen Menschen auf der Flucht, die meisten innerhalb ihres Landes oder in Nachbarländern. In Deutschland gilt <b>Artikel 16a GG</b>: „Politisch Verfolgte genießen Asylrecht.“ Daneben gilt die <b>Genfer Flüchtlingskonvention</b> von 1951 (Schutz vor Verfolgung wegen Rasse, Religion, Nationalität, politischer Meinung oder Gruppenzugehörigkeit). Über Anträge entscheidet das Bundesamt für Migration und Flüchtlinge (BAMF). Wer Krieg entflieht, erhält meist subsidiären Schutz.</p>
<p><b>Entwicklungszusammenarbeit</b> (früher „Entwicklungshilfe“) soll Armut bekämpfen und Partnerländer stärken – durch Bildung, Gesundheit, Infrastruktur und faire Handelsregeln. Die UN haben als Ziel vereinbart, <b>0,7 Prozent</b> der Wirtschaftsleistung dafür auszugeben. Kritisiert wird, dass Hilfe Abhängigkeit schaffen kann; deshalb spricht man von Zusammenarbeit auf Augenhöhe.</p>
<p>Auf den jährlichen <b>UN-Klimakonferenzen</b> (COP) verhandeln fast alle Staaten über Klimaschutz. Im <b>Pariser Abkommen 2015</b> verpflichteten sie sich, die Erderwärmung auf deutlich unter 2 Grad, möglichst 1,5 Grad gegenüber vorindustrieller Zeit zu begrenzen; jedes Land legt eigene Ziele vor. <b>Konflikte</b> sollen friedlich gelöst werden: durch Verhandlungen, Vermittlung (Mediation) durch Dritte, Sanktionen, internationale Gerichte oder UN-Friedensmissionen – Gewalt ist nur zur Selbstverteidigung oder mit UN-Mandat erlaubt.</p>`,
      aufgaben: [
        { t: "wahl", f: "Wann und warum wurden die Vereinten Nationen gegründet?", a: ["1919, um den Versailler Vertrag zu überwachen", "1945, um nach dem Zweiten Weltkrieg den Frieden zu sichern", "1989, um den Kalten Krieg zu beenden", "2001, als Reaktion auf den Terror"], r: 1, info: "Die UN-Charta trat am 24. Oktober 1945 in Kraft; heute sind 193 Staaten Mitglied." },
        { t: "wahl", f: "Wie viele Mitglieder hat der UN-Sicherheitsrat?", a: ["5", "10", "15", "193"], r: 2, info: "Fünf ständige Mitglieder mit Vetorecht und zehn nichtständige, die für zwei Jahre gewählt werden." },
        { t: "wahl", f: "Welche Staaten sind die fünf ständigen Mitglieder des Sicherheitsrats mit Vetorecht?", a: ["USA, Russland, China, Frankreich, Großbritannien", "USA, Deutschland, Japan, Indien, Brasilien", "USA, Kanada, Mexiko, Frankreich, Italien", "China, Indien, Russland, Südafrika, Brasilien"], r: 0, info: "Es sind die Siegermächte des Zweiten Weltkriegs; die Zusammensetzung wird oft kritisiert." },
        { t: "wahl", f: "Was bewirkt ein Veto im Sicherheitsrat?", a: ["Der Beschluss wird sofort gültig", "Der Beschluss ist blockiert, auch wenn alle anderen zustimmen", "Der Staat verlässt die UN", "Die Generalversammlung muss abstimmen"], r: 1, info: "Deshalb kann der Sicherheitsrat bei Konflikten, an denen eine Vetomacht beteiligt ist, oft nicht handeln." },
        { t: "wahl", f: "Was sind Blauhelme?", a: ["UN-Friedenssoldaten, die Waffenstillstände überwachen", "Soldaten der NATO", "Polizisten in Deutschland", "Mitarbeiter der WHO"], r: 0, info: "Blauhelme werden von Mitgliedstaaten gestellt und dürfen in der Regel nur zur Selbstverteidigung schießen." },
        { t: "wahl", f: "Wann wurde die Allgemeine Erklärung der Menschenrechte verabschiedet?", a: ["1789", "1919", "1948", "1990"], r: 2, info: "Am 10. Dezember 1948 – deshalb ist der 10. Dezember der Tag der Menschenrechte." },
        { t: "wahl", f: "Welche Aussage über Menschenrechte ist richtig?", a: ["Sie gelten nur für Staatsbürger reicher Länder", "Sie müssen durch gute Leistungen verdient werden", "Sie gelten für alle Menschen von Geburt an und können nicht entzogen werden", "Sie gelten nur in Kriegszeiten"], r: 2, info: "Menschenrechte sind universell, unveräußerlich und unteilbar." },
        { t: "wahl", f: "Was besagt Artikel 5 des NATO-Vertrags?", a: ["Alle Mitglieder müssen den Euro einführen", "Ein Angriff auf ein Mitglied gilt als Angriff auf alle", "Die NATO darf überall eingreifen", "Jedes Mitglied muss Atomwaffen besitzen"], r: 1, info: "Der Bündnisfall wurde bisher nur einmal ausgerufen: nach den Anschlägen vom 11. September 2001." },
        { t: "wahl", f: "Warum nennt man die Bundeswehr eine Parlamentsarmee?", a: ["Weil Abgeordnete als Soldaten dienen müssen", "Weil der Bundestag jedem Auslandseinsatz zustimmen muss", "Weil sie das Parlament bewacht", "Weil der Bundespräsident sie befehligt"], r: 1, info: "Die Kontrolle durch das Parlament ist eine Lehre aus der deutschen Geschichte." },
        { t: "wahl", f: "Welche Faktoren nennt man Push-Faktoren bei Migration?", a: ["Gründe im Herkunftsland, die Menschen wegtreiben, etwa Krieg oder Armut", "Gründe im Zielland, die Menschen anziehen, etwa Arbeit", "Die Kosten der Reise", "Die Sprache des Ziellandes"], r: 0, info: "Pull-Faktoren sind dagegen die Anziehungskräfte des Ziellandes wie Sicherheit und Arbeit." },
        { t: "wahl", f: "Was steht in Artikel 16a des Grundgesetzes?", a: ["Jeder darf in Deutschland arbeiten", "Politisch Verfolgte genießen Asylrecht", "Die Grenzen sind für alle offen", "Flüchtlinge müssen Deutsch lernen"], r: 1, info: "Das Asylrecht ist ein Grundrecht; über Anträge entscheidet das BAMF." },
        { t: "wahl", f: "Wie viel Prozent der Wirtschaftsleistung sollen reiche Länder laut UN-Ziel für Entwicklungszusammenarbeit ausgeben?", a: ["0,07 %", "0,7 %", "7 %", "17 %"], r: 1, info: "Das 0,7-Prozent-Ziel stammt aus den 1970er-Jahren; nur wenige Länder erreichen es dauerhaft." },
        { t: "wahl", f: "Was wurde im Pariser Klimaabkommen 2015 vereinbart?", a: ["Ein Verbot aller Autos bis 2030", "Die Erderwärmung auf deutlich unter 2 Grad, möglichst 1,5 Grad zu begrenzen", "Die Abschaffung der Klimakonferenzen", "Dass nur Industrieländer Klimaschutz betreiben müssen"], r: 1, info: "Jedes Land legt eigene Klimaziele vor und muss regelmäßig berichten." },
        { t: "wahl", f: "Welche Mittel gehören zur friedlichen Konfliktlösung zwischen Staaten?", a: ["Verhandlungen, Vermittlung, Sanktionen und internationale Gerichte", "Angriffskriege", "Geheime Anschläge", "Grenzen schließen und schweigen"], r: 0, info: "Gewalt ist nach der UN-Charta nur zur Selbstverteidigung oder mit UN-Mandat erlaubt." },
        { t: "eingabe", f: "Wie heißt das Verteidigungsbündnis, dem Deutschland seit 1955 angehört? (Abkürzung)", l: ["NATO", "Nato", "North Atlantic Treaty Organization"], info: "Die NATO wurde 1949 gegründet und hat heute 32 Mitglieder." },
        { t: "eingabe", f: "Wie heißt das Abkommen von 1951, das Flüchtlinge völkerrechtlich schützt? Genfer ___", l: ["Flüchtlingskonvention", "Genfer Flüchtlingskonvention", "Fluechtlingskonvention"], info: "Sie definiert, wer Flüchtling ist, und verbietet die Abschiebung in Verfolgerstaaten." },
        { t: "paare", f: "Ordne die Organisationen ihren Aufgaben zu", p: [["Sicherheitsrat", "Entscheidet über Frieden und Krieg"], ["Generalversammlung", "Jeder Staat hat eine Stimme"], ["UNICEF", "Kinderhilfswerk"], ["UNHCR", "Flüchtlingshilfswerk"], ["WHO", "Weltgesundheitsorganisation"]] },
        { t: "reihenfolge", f: "Bringe die Ereignisse in die richtige zeitliche Reihenfolge", items: ["Gründung der Vereinten Nationen", "Allgemeine Erklärung der Menschenrechte", "Gründung der NATO", "Genfer Flüchtlingskonvention", "Pariser Klimaabkommen"] }
      ]
    },
    {
      id: "medien-extremismus",
      titel: "Medien, Extremismus, Demokratie schützen",
      kurz: "Fake News, Filterblase, Pressefreiheit, öffentlich-rechtlicher Rundfunk, Extremismus, Verfassungsschutz, wehrhafte Demokratie",
      erklaerung: `<p>Demokratie braucht informierte Bürger. <b>Artikel 5 GG</b> garantiert Meinungs-, Informations- und <b>Pressefreiheit</b>; eine Zensur findet nicht statt. Medien gelten als „vierte Gewalt“, weil sie die Mächtigen kontrollieren. Der <b>öffentlich-rechtliche Rundfunk</b> (ARD, ZDF, Deutschlandradio) wird über den Rundfunkbeitrag finanziert und ist staatsfern organisiert; sein Auftrag ist eine unabhängige Grundversorgung mit Information, Bildung und Kultur. Private Sender und Zeitungen finanzieren sich durch Werbung und Abos.</p>
<p><b>Fake News</b> sind absichtlich verbreitete Falschmeldungen, oft um Stimmung zu machen oder Geld zu verdienen. Du erkennst sie, indem du prüfst: Wer ist der Absender (Impressum)? Berichten auch seriöse Medien darüber? Stimmen Datum und Ort? Ist das Bild echt (Rückwärtssuche)? Klingt die Überschrift übertrieben emotional? Faktenchecker wie Correctiv oder der dpa-Faktencheck helfen. In sozialen Netzwerken zeigen <b>Algorithmen</b> dir vor allem, was dich bestätigt und lange hält – so entsteht eine <b>Filterblase</b> oder <b>Echokammer</b>, in der andere Meinungen kaum noch vorkommen.</p>
<p><b>Extremismus</b> bedeutet, die <b>freiheitliche demokratische Grundordnung</b> abzulehnen – also Menschenwürde, Grundrechte, Gewaltenteilung, freie Wahlen und Mehrparteiensystem. <b>Rechtsextremismus</b> setzt auf Nationalismus, Rassismus, Antisemitismus, den Glauben an eine „Volksgemeinschaft“ und ein autoritäres Führerprinzip. <b>Linksextremismus</b> will den Staat und den Kapitalismus notfalls mit Gewalt überwinden und lehnt den Rechtsstaat ab. <b>Islamismus</b> stellt eine religiöse Ordnung über die Demokratie und will Gesetze nach seiner Auslegung der Religion erzwingen – er ist nicht mit dem Islam als Religion zu verwechseln. Alle Formen teilen: Feindbilder, Schwarz-Weiß-Denken, Verschwörungserzählungen und Gewaltbereitschaft.</p>
<p>Der <b>Verfassungsschutz</b> (Bundesamt in Köln und Landesämter) beobachtet extremistische Bestrebungen, sammelt Informationen und berichtet jährlich. Er ist keine Polizei und darf niemanden festnehmen (Trennungsgebot). Deutschland versteht sich als <b>wehrhafte Demokratie</b>: Lehre aus Weimar ist, dass Demokratie sich gegen ihre Feinde schützen muss. Dazu gehören das <b>Parteiverbot</b> (Artikel 21 GG – nur das Bundesverfassungsgericht kann es aussprechen, auf Antrag von Bundestag, Bundesrat oder Bundesregierung; bisher 1952 die SRP und 1956 die KPD), die Verwirkung von Grundrechten (Artikel 18), die <b>Ewigkeitsklausel</b> (Artikel 79 Absatz 3: Menschenwürde, Demokratie und Bundesstaat dürfen nie geändert werden) und das Widerstandsrecht (Artikel 20 Absatz 4).</p>
<p>Demokratie schützt sich aber vor allem durch ihre Bürger: <b>Zivilcourage</b> heißt, bei Beleidigungen, Rassismus oder Gewalt nicht wegzusehen, sondern Hilfe zu holen, Betroffene zu unterstützen und Position zu beziehen – ohne sich selbst zu gefährden. <b>Hate Speech</b> (Hassrede) im Netz ist oft strafbar (Beleidigung, Volksverhetzung nach Paragraf 130 StGB). Du kannst sie bei der Plattform melden, Screenshots sichern, Meldestellen wie HateAid einschalten oder Anzeige bei der Polizei erstatten.</p>`,
      aufgaben: [
        { t: "wahl", f: "Welcher Artikel des Grundgesetzes schützt Meinungs- und Pressefreiheit?", a: ["Artikel 1", "Artikel 5", "Artikel 16a", "Artikel 21"], r: 1, info: "Artikel 5 garantiert Meinungs-, Informations-, Presse- und Rundfunkfreiheit; Zensur ist verboten." },
        { t: "wahl", f: "Warum nennt man Medien die „vierte Gewalt“?", a: ["Weil sie Gesetze beschließen", "Weil sie Regierung, Parlament und Gerichte kontrollieren und Missstände aufdecken", "Weil sie Polizeiaufgaben übernehmen", "Weil sie vom Staat gelenkt werden"], r: 1, info: "Freie Medien sind neben Legislative, Exekutive und Judikative eine Kontrollinstanz der Demokratie." },
        { t: "wahl", f: "Wie wird der öffentlich-rechtliche Rundfunk finanziert?", a: ["Vor allem durch den Rundfunkbeitrag", "Nur durch Werbung", "Durch die Bundesregierung", "Durch Spenden"], r: 0, info: "So soll er unabhängig von Staat und Werbekunden berichten können." },
        { t: "wahl", f: "Welches Vorgehen hilft, Fake News zu erkennen?", a: ["Die Nachricht sofort teilen, damit andere prüfen", "Nur auf die Zahl der Likes achten", "Absender, Datum und weitere seriöse Quellen prüfen, Bilder rückwärts suchen", "Nur Nachrichten glauben, die zur eigenen Meinung passen"], r: 2, info: "Faktenchecker wie Correctiv oder dpa-Faktencheck helfen zusätzlich." },
        { t: "wahl", f: "Was ist eine Filterblase?", a: ["Ein Programm gegen Viren", "Der Zustand, dass Algorithmen dir vor allem Inhalte zeigen, die deine Meinung bestätigen", "Ein Filter für Fotos", "Eine geschlossene Chatgruppe der Regierung"], r: 1, info: "In der Filterblase oder Echokammer verschwinden andere Meinungen aus dem Blickfeld." },
        { t: "wahl", f: "Was kennzeichnet Extremismus allgemein?", a: ["Eine Meinung, die nicht alle teilen", "Die Ablehnung der freiheitlichen demokratischen Grundordnung", "Laute Kritik an der Regierung", "Die Teilnahme an Demonstrationen"], r: 1, info: "Kritik ist erlaubt und erwünscht; Extremisten wollen Grundrechte, Gewaltenteilung oder freie Wahlen abschaffen." },
        { t: "wahl", f: "Welche Merkmale gehören zum Rechtsextremismus?", a: ["Nationalismus, Rassismus, Antisemitismus und Führerprinzip", "Abschaffung des Kapitalismus und Klassenkampf", "Religiöse Gesetze über der Verfassung", "Forderung nach mehr Umweltschutz"], r: 0, info: "Rechtsextreme werten Menschen nach Herkunft ab und lehnen Gleichheit und Pluralismus ab." },
        { t: "wahl", f: "Was will der Linksextremismus?", a: ["Eine Monarchie einführen", "Staat und Kapitalismus notfalls mit Gewalt überwinden", "Religiöse Gesetze durchsetzen", "Die Grenzen schließen"], r: 1, info: "Linksextremisten lehnen den Rechtsstaat ab und rechtfertigen Gewalt, zum Beispiel gegen Polizei." },
        { t: "wahl", f: "Was unterscheidet Islamismus vom Islam?", a: ["Es gibt keinen Unterschied", "Islamismus ist eine politische Ideologie, die eine religiöse Ordnung über die Demokratie stellt; der Islam ist eine Religion", "Islamismus ist eine Glaubensrichtung des Islam", "Islamismus gibt es nur in Deutschland"], r: 1, info: "Die große Mehrheit der Muslime lehnt islamistische Positionen ab." },
        { t: "wahl", f: "Welche Aufgabe hat der Verfassungsschutz?", a: ["Er verhaftet Extremisten", "Er beobachtet extremistische Bestrebungen und informiert Politik und Öffentlichkeit", "Er schreibt das Grundgesetz um", "Er entscheidet über Parteiverbote"], r: 1, info: "Der Verfassungsschutz ist ein Nachrichtendienst, keine Polizei (Trennungsgebot)." },
        { t: "wahl", f: "Wer kann in Deutschland eine Partei verbieten?", a: ["Der Bundeskanzler", "Der Bundestag mit einfacher Mehrheit", "Nur das Bundesverfassungsgericht", "Der Verfassungsschutz"], r: 2, info: "Artikel 21 GG: Antrag von Bundestag, Bundesrat oder Bundesregierung; verboten wurden 1952 die SRP und 1956 die KPD." },
        { t: "wahl", f: "Was meint „wehrhafte Demokratie“?", a: ["Dass die Demokratie sich mit Verboten und Kontrollen gegen ihre Feinde schützen darf", "Dass jeder Bürger Soldat sein muss", "Dass die Polizei die Regierung stellt", "Dass Wahlen abgeschafft werden können"], r: 0, info: "Die Lehre aus dem Untergang der Weimarer Republik: Freiheit darf nicht zur Abschaffung der Freiheit genutzt werden." },
        { t: "wahl", f: "Was legt die Ewigkeitsklausel (Artikel 79 Absatz 3 GG) fest?", a: ["Das Grundgesetz gilt nur 100 Jahre", "Menschenwürde, Demokratie und Bundesstaat dürfen nie geändert werden", "Der Bundeskanzler regiert auf Lebenszeit", "Die Länder dürfen austreten"], r: 1, info: "Selbst mit Zweidrittelmehrheit kann der Kern des Grundgesetzes nicht angetastet werden." },
        { t: "wahl", f: "Was ist Zivilcourage?", a: ["Sich selbst in jede Prügelei einmischen", "Bei Unrecht nicht wegsehen, Hilfe holen und Betroffene unterstützen, ohne sich selbst zu gefährden", "Alles der Polizei überlassen", "Im Internet anonym bleiben"], r: 1, info: "Ansprechen, Umstehende einbeziehen, Notruf 110 wählen, als Zeuge bereitstehen." },
        { t: "wahl", f: "Was kannst du gegen Hate Speech im Netz tun?", a: ["Mit Beleidigungen zurückschlagen", "Nichts, das Internet ist rechtsfrei", "Melden bei der Plattform, Screenshots sichern, Meldestellen oder Polizei einschalten", "Den Beitrag teilen, damit alle ihn sehen"], r: 2, info: "Beleidigung und Volksverhetzung (Paragraf 130 StGB) sind auch online strafbar." },
        { t: "eingabe", f: "Wie nennt man absichtlich verbreitete Falschmeldungen? (englischer Begriff, zwei Wörter)", l: ["Fake News", "Fakenews", "Fake-News"], info: "Im Gegensatz zu einem Irrtum werden Fake News bewusst gestreut, um zu täuschen." },
        { t: "paare", f: "Ordne die Grundgesetz-Artikel ihrem Inhalt zu", p: [["Artikel 5", "Meinungs- und Pressefreiheit"], ["Artikel 18", "Verwirkung von Grundrechten"], ["Artikel 21", "Parteien und Parteiverbot"], ["Artikel 79 Absatz 3", "Ewigkeitsklausel"]] },
        { t: "paare", f: "Ordne die Begriffe zu", p: [["Echokammer", "Nur noch bestätigende Meinungen hören"], ["Verfassungsschutz", "Beobachtet Extremisten, keine Polizei"], ["Rundfunkbeitrag", "Finanziert ARD, ZDF, Deutschlandradio"], ["Zivilcourage", "Hinsehen und helfen bei Unrecht"]] }
      ]
    },
    {
      id: "nachhaltigkeit",
      titel: "Nachhaltigkeit und Wirtschaft",
      kurz: "17 SDGs, ökologischer Fußabdruck, Kreislaufwirtschaft, CO2-Preis, Lieferkette, Konsum, Energiewende, Zielkonflikte",
      erklaerung: `<p><b>Nachhaltigkeit</b> heißt nach der Definition der Brundtland-Kommission (1987): so leben und wirtschaften, dass die Bedürfnisse von heute erfüllt werden, ohne dass künftige Generationen ihre Bedürfnisse nicht mehr erfüllen können. Nachhaltigkeit hat <b>drei Dimensionen</b>: <b>Ökologie</b> (Umwelt, Klima, Artenvielfalt), <b>Ökonomie</b> (Wohlstand, Arbeitsplätze) und <b>Soziales</b> (Gerechtigkeit, Gesundheit, Bildung). Der Begriff stammt aus der Forstwirtschaft: Nur so viel Holz schlagen, wie nachwächst.</p>
<p>2015 beschlossen die Vereinten Nationen die <b>Agenda 2030</b> mit <b>17 Zielen für nachhaltige Entwicklung</b> (Sustainable Development Goals, <b>SDGs</b>): zum Beispiel keine Armut, kein Hunger, hochwertige Bildung, Geschlechtergleichheit, sauberes Wasser, bezahlbare und saubere Energie, menschenwürdige Arbeit, nachhaltiger Konsum, Klimaschutz, Leben unter Wasser und an Land, Frieden und Partnerschaften. Sie gelten für alle Länder – auch für Deutschland.</p>
<p>Der <b>ökologische Fußabdruck</b> misst, wie viel Fläche nötig ist, um den Verbrauch eines Menschen zu decken und seine Abfälle und sein CO2 aufzunehmen. Würden alle so leben wie in Deutschland, bräuchten wir etwa drei Erden. Der <b>Erdüberlastungstag</b> markiert den Tag im Jahr, an dem die Menschheit die Ressourcen verbraucht hat, die die Erde in einem Jahr erneuern kann – er liegt inzwischen im Sommer. Größte Posten sind Wohnen (Heizen, Strom), Mobilität (Auto, Flug), Ernährung (vor allem Fleisch) und Konsum.</p>
<p>In der <b>linearen Wirtschaft</b> gilt: herstellen – nutzen – wegwerfen. Die <b>Kreislaufwirtschaft</b> will Rohstoffe im Kreis führen: Produkte länger nutzen, reparieren, teilen, wiederverwenden und am Ende recyceln (Reduce, Reuse, Repair, Recycle). Dazu gehören das Recht auf Reparatur, Pfandsysteme und langlebiges Design.</p>
<p>Ein zentrales Instrument ist der <b>CO2-Preis</b>: Wer CO2 ausstößt, muss dafür bezahlen – so wird Klimaschädliches teurer und Klimafreundliches lohnt sich. In der EU gibt es seit 2005 den Emissionshandel für Industrie und Kraftwerke; in Deutschland gilt seit 2021 ein nationaler CO2-Preis auf Benzin, Diesel, Heizöl und Gas. Das deutsche <b>Lieferkettengesetz</b> (2023) verpflichtet große Unternehmen, bei ihren Zulieferern auf Menschenrechte und Umweltschutz zu achten – etwa gegen Kinderarbeit in Textilfabriken oder Kobaltminen. Als Verbraucher hast du <b>Verantwortung</b>: Siegel wie Fairtrade, Bio-Siegel oder Blauer Engel helfen bei der Wahl; Vorsicht vor <b>Greenwashing</b>, wenn Firmen sich grüner darstellen, als sie sind.</p>
<p>Die <b>Energiewende</b> ersetzt Kohle, Öl, Gas und Atomkraft durch erneuerbare Energien (Wind, Sonne, Wasser, Biomasse). Die letzten deutschen Atomkraftwerke gingen im April 2023 vom Netz; erneuerbare Energien liefern inzwischen mehr als die Hälfte des Stroms, bis <b>2045</b> will Deutschland klimaneutral sein. Dabei gibt es <b>Zielkonflikte</b>: Windräder gegen Landschafts- und Vogelschutz, Kohleausstieg gegen Arbeitsplätze in der Lausitz, höhere CO2-Preise gegen bezahlbares Heizen für Menschen mit wenig Geld. Nachhaltige Politik muss Ökologie, Ökonomie und Soziales gegeneinander abwägen.</p>`,
      aufgaben: [
        { t: "wahl", f: "Was bedeutet Nachhaltigkeit nach der Brundtland-Definition?", a: ["Möglichst viel produzieren, damit alle Arbeit haben", "Heutige Bedürfnisse erfüllen, ohne dass künftige Generationen ihre Bedürfnisse nicht mehr erfüllen können", "Alle Fabriken schließen", "Nur noch regionale Produkte kaufen"], r: 1, info: "Der Begriff stammt aus der Forstwirtschaft: nur so viel Holz schlagen, wie nachwächst." },
        { t: "wahl", f: "Welche drei Dimensionen hat Nachhaltigkeit?", a: ["Ökologie, Ökonomie, Soziales", "Politik, Wirtschaft, Militär", "Wasser, Luft, Boden", "Stadt, Land, Meer"], r: 0, info: "Umwelt, Wohlstand und Gerechtigkeit müssen zusammen gedacht werden." },
        { t: "wahl", f: "Wie viele Ziele für nachhaltige Entwicklung (SDGs) haben die Vereinten Nationen 2015 beschlossen?", a: ["7", "10", "17", "30"], r: 2, info: "Die 17 SDGs der Agenda 2030 reichen von „Keine Armut“ bis „Partnerschaften zur Erreichung der Ziele“." },
        { t: "wahl", f: "Für wen gelten die SDGs?", a: ["Nur für Entwicklungsländer", "Nur für Industrieländer", "Für alle Staaten, auch Deutschland", "Nur für Unternehmen"], r: 2, info: "Anders als frühere Ziele richten sich die SDGs an alle Länder der Welt." },
        { t: "wahl", f: "Was misst der ökologische Fußabdruck?", a: ["Die Schuhgröße eines Menschen", "Die Fläche, die nötig ist, um den Verbrauch eines Menschen zu decken und seine Abfälle aufzunehmen", "Die Zahl der Bäume in einem Land", "Den Preis für CO2"], r: 1, info: "Würden alle wie in Deutschland leben, bräuchte die Menschheit etwa drei Erden." },
        { t: "wahl", f: "Was bedeutet der Erdüberlastungstag?", a: ["Der Tag, an dem die Menschheit die Ressourcen eines ganzen Jahres verbraucht hat", "Der Tag mit der höchsten Temperatur", "Der Tag, an dem die UN gegründet wurden", "Der Tag, an dem alle Fabriken stillstehen"], r: 0, info: "Er liegt inzwischen im Sommer – den Rest des Jahres leben wir auf Kosten der Zukunft." },
        { t: "wahl", f: "Was unterscheidet die Kreislaufwirtschaft von der linearen Wirtschaft?", a: ["In der Kreislaufwirtschaft werden Produkte länger genutzt, repariert, wiederverwendet und recycelt", "In der Kreislaufwirtschaft wird alles weggeworfen", "Die lineare Wirtschaft kennt kein Geld", "Es gibt keinen Unterschied"], r: 0, info: "Linear heißt: herstellen – nutzen – wegwerfen. Im Kreislauf bleiben Rohstoffe erhalten." },
        { t: "wahl", f: "Wie wirkt ein CO2-Preis?", a: ["Er verbietet den Ausstoß von CO2", "Er macht klimaschädliche Produkte teurer, sodass klimafreundliche Alternativen attraktiver werden", "Er senkt den Benzinpreis", "Er gilt nur für Privatpersonen"], r: 1, info: "In Deutschland gilt seit 2021 ein CO2-Preis auf Benzin, Diesel, Heizöl und Gas; die EU hat seit 2005 den Emissionshandel." },
        { t: "wahl", f: "Was verlangt das Lieferkettengesetz von großen Unternehmen?", a: ["Nur in Deutschland zu produzieren", "Bei ihren Zulieferern auf Menschenrechte und Umweltschutz zu achten", "Alle Produkte per Schiff zu liefern", "Die Preise zu senken"], r: 1, info: "Es richtet sich zum Beispiel gegen Kinderarbeit und Zwangsarbeit in Textilfabriken oder Minen." },
        { t: "wahl", f: "Was ist Greenwashing?", a: ["Das Waschen von Kleidung bei niedriger Temperatur", "Wenn Firmen sich umweltfreundlicher darstellen, als sie wirklich sind", "Ein Siegel für Bio-Produkte", "Das Recycling von Glas"], r: 1, info: "Vage Begriffe wie „klimafreundlich“ ohne Nachweis sind ein Warnsignal; seriöse Siegel haben klare Kriterien." },
        { t: "wahl", f: "Was bedeutet Energiewende?", a: ["Den Umstieg von Kohle, Öl, Gas und Atomkraft auf erneuerbare Energien", "Den Bau neuer Kohlekraftwerke", "Das Abschalten des Stroms am Abend", "Den Import von Strom aus dem Ausland"], r: 0, info: "Deutschland hat 2023 die letzten Atomkraftwerke abgeschaltet und will bis 2045 klimaneutral sein." },
        { t: "wahl", f: "Welches Beispiel ist ein typischer Zielkonflikt der Nachhaltigkeit?", a: ["Kohleausstieg für das Klima gegen Arbeitsplätze in den Kohleregionen", "Mehr Fahrradwege gegen weniger Fahrradwege", "Sonne gegen Regen", "Schule gegen Ferien"], r: 0, info: "Ökologische, ökonomische und soziale Ziele können sich widersprechen; Politik muss abwägen." },
        { t: "wahl", f: "Was kannst du als Verbraucher für mehr Nachhaltigkeit tun?", a: ["Möglichst oft neue Kleidung kaufen", "Produkte länger nutzen, reparieren, auf Siegel achten und weniger wegwerfen", "Alles im Internet bestellen und zurückschicken", "Nur noch Plastikflaschen kaufen"], r: 1, info: "Konsumentscheidungen sind ein Hebel – Politik und Unternehmen tragen aber die größere Verantwortung." },
        { t: "zahl", f: "Ein Flug verursacht 2 Tonnen CO2. Der CO2-Preis beträgt 55 € pro Tonne. Wie viel würde das CO2 des Fluges kosten? (in €)", l: 110, tol: 0.5, einheit: "€", info: "2 · 55 € = 110 €." },
        { t: "zahl", f: "Ein Haushalt verbraucht 3.000 kWh Strom im Jahr und spart durch LED-Lampen und sparsame Geräte 15 %. Wie viel kWh verbraucht er danach? (in kWh)", l: 2550, tol: 0.5, einheit: "kWh", info: "15 % von 3.000 kWh sind 450 kWh; 3.000 − 450 = 2.550 kWh." },
        { t: "eingabe", f: "Wie heißt das Wirtschaftsmodell, in dem Rohstoffe durch Reparieren, Wiederverwenden und Recycling im Kreis geführt werden? ___wirtschaft", l: ["Kreislaufwirtschaft", "Kreislauf"], info: "Gegenteil ist die lineare Wegwerfwirtschaft." },
        { t: "paare", f: "Ordne die Begriffe ihrer Bedeutung zu", p: [["SDGs", "17 UN-Nachhaltigkeitsziele"], ["Ökologischer Fußabdruck", "Flächenbedarf für den eigenen Verbrauch"], ["CO2-Preis", "Ausstoß von Treibhausgasen kostet Geld"], ["Greenwashing", "Scheinbar grünes Image"], ["Lieferkettengesetz", "Verantwortung für Zulieferer"]] },
        { t: "reihenfolge", f: "Bringe die Stufen der Kreislaufwirtschaft in die richtige Reihenfolge (von der besten zur letzten Option)", items: ["Vermeiden: gar nicht erst kaufen (Reduce)", "Wiederverwenden: gebraucht kaufen oder teilen (Reuse)", "Reparieren statt neu kaufen (Repair)", "Recyceln: Rohstoffe zurückgewinnen (Recycle)"] }
      ]
    }
  );
})();
